@startuml

enum Interval {
  Weekly
  Monthly
  EveryHalfYear
  Yearly
}

class Doctor {
  +practitionerNumber : string
  +signature : string
  +fullName : string
  +address : string
  +phoneNumber : string
}

class Patient {
  +healthNumber : string
  +firstName : string
  +lastName : string
  +dateOfBirth : date
  +address : string
  +phoneNumber : string
}

class Requisition {
  +validFromDate : date
}

class SpecificTest {
  +repetitionCount : int
  +repetitionInterval : Interval
}

class Test {
  +duration : int
}

class TestGroup {
}

class TestResult {
  +isPositive : boolean
  +report : string
}

class Appointment {
  +confirmationNumber : string
  +startDate : datetime
  +endDate : datetime
}

class Lab {
  +address : string
  +registrationNumber : string
  +businessHours : string
  +fee : float
}

Doctor "1" -- "*" Requisition : prescribes
Patient "1" -- "*" Requisition : is subject of
Requisition "1" *-- "1..*" SpecificTest : contains
SpecificTest "1" -- "1" Test : is a type of
Test "*" -- "1" TestGroup : belongs to
SpecificTest "0..1" -- "1" TestResult : has
Doctor "1" -- "*" TestResult : views
Patient "1" -- "*" TestResult : views
Patient "1" -- "*" Appointment : makes
Appointment "1" -- "1" Requisition : for
Appointment "1" -- "1" Lab : at
Lab "1" -- "*" Appointment : hosts

@enduml

